import fs from "fs"



async function  fetchWithFallback<T>( url : string ,localPath : string) : Promise <T | null> {
  try {
    // $$$$$
    // to log fetching remote config URL
    // console.log(`[Targeting] Fetching remote config from: ${url}`);

    const response = await fetch(url, { signal: AbortSignal.timeout(5000) });
    if (response.ok) {
      const json = await response.json();
      return json;
    }
  } catch (error) {
    console.log(error)
  
  }

  try {
    const data =  fs.readFileSync(localPath, "utf-8");
    return JSON.parse(data);
  } catch (error) {
    return null;
  }
}




export { fetchWithFallback  }